function buildGeneratedImageMarkdown(result = {}) {
    const images = Array.isArray(result?.images) ? result.images : [];
    return images
        .map((image, index) => {
            const url = String(image?.url || '').trim();
            if (!url || !url.startsWith(GENERATED_IMAGE_PUBLIC_PREFIX + '/')) return '';
            return `![生成图片 ${index + 1}](${url})`;
        })
        .filter(Boolean)
        .join('\n\n');
}

function buildArtifactDownloadMarkdown(result = {}) {
    const rawUrl = String(result?.downloadPath || '').trim();
    try {
        const parsed = new URL(rawUrl, 'http://rai.local');
        if (
            parsed.origin !== 'http://rai.local'
            || !/^\/api\/file-jobs\/[a-f0-9]{48}\/artifacts\/[a-f0-9]{32}$/i.test(parsed.pathname)
            || !parsed.searchParams.get('sessionId')
            || [...parsed.searchParams.keys()].some((key) => key !== 'sessionId')
        ) return '';
        const label = String(result?.fileName || 'RAI 文件产物')
            .replace(/[\u0000-\u001f\u007f\[\]();\\]/g, '_')
            .slice(0, 96) || 'RAI 文件产物';
        return `[下载 ${label}](${parsed.pathname}${parsed.search})`;
    } catch (_) {
        return '';
    }
}

function appendRaiRuntimeReport(entry = {}) {
    let block;
    try {
        const level = sanitizeReportLabel(entry.level, '报错');
        const tag = sanitizeReportLabel(entry.tag, 'runtime');
        const message = summarizePrivateValue(entry.message || '', 'message');
        const context = sanitizeReportContext(entry.context || {});
        block = [
            '',
            `## ${new Date().toISOString()} ${level} ${tag}`,
            `- message: ${JSON.stringify(message)}`,
            '- context:',
            '```json',
            JSON.stringify(context, null, 2),
            '```',
            ''
        ].join('\n');
    } catch (error) {
        console.warn(' RAI 运行报告内容拒绝写入:', {
            errorName: String(error?.name || 'Error').slice(0, 80),
            errorCode: String(error?.code || 'sanitize_failed').slice(0, 80)
        });
        return Promise.resolve(false);
    }

    return writeRuntimeReportBlock(block)
        .then(() => true)
        .catch((error) => {
            console.warn(' 写入 RAI 运行报告失败:', {
                errorName: String(error?.name || 'Error').slice(0, 80),
                errorCode: String(error?.code || 'write_failed').slice(0, 80)
            });
            return false;
        });
}

