app.delete('/api/user/passkeys/:id', authenticateToken, authLimiter, async (req, res) => {
    try {
        await databaseSchemaReady;
        setPasskeyNoStore(res);
        const passkeyId = Number(req.params.id);
        const grant = String(req.body?.grant || '');
        if (!Number.isInteger(passkeyId) || passkeyId <= 0 || !grant) {
            throw buildPasskeyHttpError('请先完成安全验证', 401, 'passkey_reauth_required');
        }
        await withSensitiveAccountMutation(req.user.userId, async (tx) => {
            await consumePasskeyReauthGrantUsingTransaction(tx, {
                token: grant,
                userId: req.user.userId,
                scope: 'passkey:delete'
            });
            const deletion = await tx.run(
                'DELETE FROM webauthn_credentials WHERE id = ? AND user_id = ?',
                [passkeyId, req.user.userId]
            );
            if (Number(deletion?.changes || 0) !== 1) {
                throw buildPasskeyHttpError('通行密钥不存在', 404, 'passkey_not_found');
            }
            return deletion;
        });
        await purgeStaleAuthSessionsAfterSensitiveChange(req.user.userId, 'passkey_deleted');
        const updatedUser = await dbGetAsync('SELECT * FROM users WHERE id = ?', [req.user.userId]);
        const replacement = await buildAuthenticatedUserPayload(
            updatedUser,
            req,
            '',
            { auth_method: 'passkey_management' }
        );
        return res.json({
            success: true,
            deletedPasskeyId: passkeyId,
            token: replacement.token,
            tokenExpiresAt: replacement.tokenExpiresAt
        });
    } catch (error) {
        return sendPasskeyRouteError(res, error, '删除通行密钥失败');
    }
});

app.post('/api/user/2fa/setup', authenticateToken, async (req, res) => {
    try {
        const user = await dbGetAsync(
            `SELECT id, email, username, password_hash, external_provider,
                    two_factor_enabled, two_factor_secret
             FROM users WHERE id = ?`,
            [req.user.userId]
        );

        if (!user) {
            return res.status(404).json({ success: false, error: '用户不存在' });
        }

        if (Number(user.two_factor_enabled || 0) === 1) {
            return res.status(409).json({ success: false, error: '二步验证已开启' });
        }

        await verifyPasskeyReauthentication(req, user, req.body || {});

        const secret = generateTotpSecret();
        const setupChallenge = await createUserTwoFactorSetupChallenge(user, secret);
        const accountName = user.email || `user-${user.id}`;
        const otpauthUrl = buildOtpAuthUrl({ accountName, secret });
        const qrDataUrl = await QRCode.toDataURL(otpauthUrl, {
            errorCorrectionLevel: 'M',
            margin: 1,
            width: 192
        });

        res.json({
            success: true,
            secret,
            otpauthUrl,
            qrDataUrl,
            setupToken: buildUserTwoFactorSetupToken(user, setupChallenge.setupId),
            expiresAt: setupChallenge.expiresAt
        });
    } catch (error) {
        console.error(' 创建二步验证设置失败:', sanitizeReportContext(error));
        res.status(error.statusCode || 500).json({
            success: false,
            error: error.statusCode ? error.message : '创建二步验证失败'
        });
    }
});

app.post('/api/user/2fa/enable', authenticateToken, async (req, res) => {
    try {
        const setupToken = typeof req.body?.setupToken === 'string' ? req.body.setupToken : '';
        const code = typeof req.body?.code === 'string' ? req.body.code : '';

        if (!setupToken || !code) {
            return res.status(400).json({ success: false, error: '二步验证码不能为空' });
        }

        let decoded;
        try {
            decoded = jwt.verify(setupToken, JWT_SECRET, {
                algorithms: ['HS256'],
                issuer: INTERMEDIATE_TOKEN_ISSUER,
                audience: TWO_FACTOR_SETUP_AUDIENCE
            });
        } catch (error) {
            return res.status(401).json({ success: false, error: '二步验证设置已过期，请重新生成' });
        }

        if (
            decoded?.type !== 'user_2fa_setup'
            || Number(decoded.userId) !== Number(req.user.userId)
            || !decoded.setupId
        ) {
            return res.status(401).json({ success: false, error: '二步验证设置无效，请重新生成' });
        }

        const setupChallenge = await consumeUserTwoFactorSetupChallenge({
            setupId: decoded.setupId,
            userId: req.user.userId
        });
        let secret = '';
        try {
            secret = normalizeTotpSecret(totpSecretCipher.decrypt(setupChallenge?.secret, {
                purpose: 'setup',
                recordId: String(decoded.setupId),
                allowPlaintext: true
            }));
        } catch (_) {
            secret = '';
        }
        if (!secret) {
            return res.status(401).json({ success: false, error: '二步验证设置已过期，请重新生成' });
        }

        const acceptedCounter = findMatchingTotpCounter(secret, code);
        if (acceptedCounter === null) {
            return res.status(400).json({ success: false, error: 'Authenticator 验证码无效' });
        }

        await databaseSchemaReady;
        const recoveryCodes = generateRecoveryCodes();
        const twoFactorMutation = await withSensitiveAccountMutation(req.user.userId, async (tx) => {
            const update = await tx.run(
                `UPDATE users
                 SET two_factor_enabled = 1,
                     two_factor_secret = ?,
                     two_factor_last_counter = ?,
                     two_factor_confirmed_at = CURRENT_TIMESTAMP
                 WHERE id = ? AND COALESCE(two_factor_enabled, 0) = 0`,
                [
                    totpSecretCipher.encrypt(secret, {
                        purpose: 'user',
                        recordId: String(req.user.userId)
                    }),
                    acceptedCounter,
                    req.user.userId
                ]
            );
            if (Number(update?.changes || 0) !== 1) {
                throw buildPasskeyHttpError('二步验证状态已变化，请刷新后重试', 409, 'two_factor_state_changed');
            }
            await tx.run(
                'DELETE FROM user_two_factor_recovery_codes WHERE user_id = ?',
                [req.user.userId]
            );
            for (const recoveryCode of recoveryCodes) {
                await tx.run(
                    `INSERT INTO user_two_factor_recovery_codes
                     (user_id, code_hash, created_at, used_at)
                     VALUES (?, ?, ?, NULL)`,
                    [req.user.userId, hashRecoveryCode(recoveryCode), Date.now()]
                );
            }
            return awardSecuritySetupRewardUsingTransaction(
                tx,
                req.user.userId,
                USER_TASK_REWARDS.securityTwoFactor,
                { securityMethod: 'totp' }
            );
        });
        const rewardPoints = twoFactorMutation.value;

        await purgeStaleAuthSessionsAfterSensitiveChange(req.user.userId, 'two_factor_enabled');
        const updatedUser = await dbGetAsync('SELECT * FROM users WHERE id = ?', [req.user.userId]);
        const replacement = await buildAuthenticatedUserPayload(
            updatedUser,
            req,
            '',
            { auth_method: 'two_factor_setup' }
        );
        console.log(` 用户二步验证已开启: userId=${req.user.userId}`);
        res.json({
            success: true,
            two_factor_enabled: true,
            rewardPoints,
            recoveryCodes,
            token: replacement.token,
            tokenExpiresAt: replacement.tokenExpiresAt
        });
    } catch (error) {
        console.error(' 开启二步验证失败:', sanitizeReportContext(error));
        res.status(error.statusCode || 500).json({
            success: false,
            error: error.statusCode ? error.message : '开启二步验证失败'
        });
    }
});

app.post('/api/user/2fa/disable', authenticateToken, async (req, res) => {
    try {
        const code = typeof req.body?.code === 'string' ? req.body.code : '';
        if (!code) {
            return res.status(400).json({ success: false, error: '二步验证码不能为空' });
        }

        const user = await dbGetAsync(
            `SELECT id, email, password_hash, external_provider,
                    two_factor_enabled, two_factor_secret, two_factor_last_counter
             FROM users WHERE id = ?`,
            [req.user.userId]
        );

        if (!user) {
            return res.status(404).json({ success: false, error: '用户不存在' });
        }

        if (Number(user.two_factor_enabled || 0) !== 1 || !hasUsableUserTotpSecret(user)) {
            return res.status(409).json({ success: false, error: '二步验证尚未开启' });
        }

        await verifyPasskeyReauthentication(req, user, {
            ...(req.body || {}),
            twoFactorCode: code
        });

        const mutation = await withSensitiveAccountMutation(req.user.userId, async (tx) => {
            const disabled = await tx.run(
                `UPDATE users
                 SET two_factor_enabled = 0,
                     two_factor_secret = NULL,
                     two_factor_last_counter = NULL,
                     two_factor_confirmed_at = NULL
                 WHERE id = ? AND COALESCE(two_factor_enabled, 0) = 1`,
                [req.user.userId]
            );
            if (Number(disabled?.changes || 0) !== 1) {
                throw buildPasskeyHttpError('二步验证状态已变化，请刷新后重试', 409, 'two_factor_state_changed');
            }
            await tx.run('DELETE FROM user_two_factor_recovery_codes WHERE user_id = ?', [req.user.userId]);
            return tx.get('SELECT * FROM users WHERE id = ?', [req.user.userId]);
        });

        await purgeStaleAuthSessionsAfterSensitiveChange(req.user.userId, 'two_factor_disabled');
        const updatedUser = { ...mutation.value, session_version: mutation.sessionVersion };
        const replacement = await buildAuthenticatedUserPayload(
            updatedUser,
            req,
            '',
            { auth_method: 'password' }
        );
        console.log(` 用户二步验证已关闭: userId=${req.user.userId}`);
        res.json({
            success: true,
            two_factor_enabled: false,
            token: replacement.token,
            tokenExpiresAt: replacement.tokenExpiresAt
        });
    } catch (error) {
        console.error(' 关闭二步验证失败:', sanitizeReportContext(error));
        res.status(error.statusCode || 500).json({
            success: false,
            error: error.statusCode ? error.message : '关闭二步验证失败'
        });
    }
});

app.put('/api/user/password', authenticateToken, async (req, res) => {
    try {
        const currentPassword = typeof req.body?.currentPassword === 'string' ? req.body.currentPassword : '';
        const newPassword = typeof req.body?.newPassword === 'string' ? req.body.newPassword : '';

        if (!currentPassword) {
            return res.status(400).json({ success: false, error: '当前密码不能为空' });
        }

        const currentPasswordError = validateExistingPasswordInput(currentPassword, '当前密码');

        if (currentPasswordError) {
            return res.status(400).json({ success: false, error: currentPasswordError });
        }

        const user = await dbGetAsync(
            'SELECT id, email, username, password_hash FROM users WHERE id = ?',
            [req.user.userId]
        );

        if (!user) {
            return res.status(404).json({ success: false, error: '用户不存在' });
        }

        const newPasswordError = await validateNewPasswordForAccount(newPassword, {
            email: user.email,
            username: user.username
        }, '新密码');
        if (newPasswordError) {
            return res.status(400).json({ success: false, error: newPasswordError });
        }

        if (newPassword === currentPassword) {
            return res.status(400).json({ success: false, error: '新密码不能与当前密码相同' });
        }

        const passwordMatched = await verifyPassword(currentPassword, user.password_hash);
        if (!passwordMatched) {
            return res.status(400).json({ success: false, error: '当前密码错误' });
        }

        const nextPasswordHash = await hashPassword(newPassword);
        if (!await verifyPassword(newPassword, nextPasswordHash).catch(() => false)) {
            throw new Error('password_change_hash_verification_failed');
        }
        const mutation = await withSensitiveAccountMutation(user.id, async (tx) => {
            const changed = await tx.run(
                `UPDATE users
                 SET password_hash = ?, password_policy_version = ?
                 WHERE id = ? AND password_hash = ?`,
                [nextPasswordHash, PASSWORD_POLICY_VERSION, user.id, user.password_hash]
            );
            if (Number(changed?.changes || 0) !== 1) {
                throw new Error('password_change_state_changed');
            }
            return tx.get('SELECT * FROM users WHERE id = ?', [user.id]);
        });

        await purgeStaleAuthSessionsAfterSensitiveChange(user.id, 'password_changed');
        const updatedUser = { ...mutation.value, session_version: mutation.sessionVersion };
        const replacement = await buildAuthenticatedUserPayload(
            updatedUser,
            req,
            '',
            { auth_method: 'password' }
        );

        console.log(` 用户密码已更新: userId=${user.id}`);
        res.json({
            success: true,
            token: replacement.token,
            tokenExpiresAt: replacement.tokenExpiresAt
        });
    } catch (error) {
        console.error(' 更新用户密码失败:', sanitizeReportContext(error));
        res.status(500).json({ success: false, error: '更新密码失败' });
    }
});

app.delete('/api/user/account', authenticateToken, async (req, res) => {
    try {
        const currentPassword = typeof req.body?.currentPassword === 'string' ? req.body.currentPassword : '';
        const confirmation = String(req.body?.confirmation || '').normalize('NFKC').trim();
        const twoFactorCode = typeof req.body?.twoFactorCode === 'string' ? req.body.twoFactorCode : '';

        if (!currentPassword) {
            return res.status(400).json({ success: false, error: '当前密码不能为空' });
        }

        if (!ACCOUNT_DELETE_CONFIRMATIONS.has(confirmation)) {
            return res.status(400).json({ success: false, error: '确认词不正确' });
        }

        const user = await dbGetAsync(
            'SELECT id, email, password_hash, two_factor_enabled, two_factor_secret FROM users WHERE id = ?',
            [req.user.userId]
        );

        if (!user) {
            return res.status(404).json({ success: false, error: '用户不存在' });
        }

        const passwordMatched = await verifyPassword(currentPassword, user.password_hash).catch(() => false);
        if (!passwordMatched) {
            return res.status(400).json({ success: false, error: '当前密码错误' });
        }

        const twoFactorEnabled = Number(user.two_factor_enabled || 0) === 1 && hasUsableUserTotpSecret(user);
        if (twoFactorEnabled && !await consumeUserSecondFactor(user, twoFactorCode)) {
            return res.status(400).json({ success: false, error: 'Authenticator 验证码无效' });
        }

        const result = await deleteUserDataCascade(user.id, { actor: 'self' });
        if (!result.success) {
            return res.status(404).json({ success: false, error: '用户不存在' });
        }

        console.log(` 用户自助注销完成: userId=${user.id}, uploads=${result.deletedUploads}, files=${result.deletedFiles}`);
        return res.json({
            success: true,
            deletedUserId: result.deletedUserId,
            deletedUploads: result.deletedUploads,
            deletedFiles: result.deletedFiles
        });
    } catch (error) {
        console.error(' 用户自助注销失败:', sanitizeReportContext(error));
        return res.status(error.statusCode || 500).json({ success: false, error: '注销账号失败' });
    }
});

function clampNumber(value, min, max, fallback) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) return fallback;
    return Math.min(Math.max(numeric, min), max);
}

function clampInteger(value, min, max, fallback) {
    return Math.round(clampNumber(value, min, max, fallback));
}

function sanitizeUserConfigPayload(payload = {}) {
    const theme = ['light', 'dark', 'system'].includes(String(payload.theme || '').trim())
        ? String(payload.theme).trim()
        : 'dark';
    // The account preference is deliberately no longer a routing choice. Manual
    // choices remain request/session-local on clients that support them.
    const safeDefaultModel = 'auto';
    const fontPreference = String(payload.font_preference || '').trim().toLowerCase() === 'rai-v1' ? 'rai-v1' : 'system';
    const allowedTabTitleModes = ['default', 'static', 'marquee', 'greeting', 'title', 'custom'];
    const tabTitleMode = allowedTabTitleModes.includes(String(payload.tab_title_mode || '').trim())
        ? String(payload.tab_title_mode).trim()
        : 'default';
    const tabTitleCustomText = String(payload.tab_title_custom_text ?? '').slice(0, 80);
    const rawSelectionExplanationDeleteMode = payload.selection_explanation_delete_mode;
    const selectionExplanationDeleteMode = rawSelectionExplanationDeleteMode === undefined
        ? null
        : (SELECTION_EXPLANATION_DELETE_MODES.has(String(rawSelectionExplanationDeleteMode || '').trim())
            ? String(rawSelectionExplanationDeleteMode).trim()
            : 'promote_children');

    return {
        theme,
        default_model: safeDefaultModel,
        temperature: clampNumber(payload.temperature, 0, 2, 0.7),
        top_p: clampNumber(payload.top_p, 0, 1, 0.9),
        max_tokens: clampInteger(payload.max_tokens, 256, 128000, 2000),
        frequency_penalty: clampNumber(payload.frequency_penalty, -2, 2, 0),
        presence_penalty: clampNumber(payload.presence_penalty, -2, 2, 0),
        system_prompt: String(payload.system_prompt ?? '').slice(0, 12000),
        thinking_mode: payload.thinking_mode ? 1 : 0,
        // Internet search is opt-out for the current chat only; it never persists as disabled.
        internet_mode: 1,
        long_memory_enabled: payload.long_memory_enabled === undefined
            ? null
            : (isLongMemoryEnabledValue(payload.long_memory_enabled) ? 1 : 0),
        font_preference: fontPreference,
        tab_title_mode: tabTitleMode,
        tab_title_custom_text: tabTitleCustomText,
        selection_explanation_delete_mode: selectionExplanationDeleteMode
    };
}

app.put('/api/user/config', authenticateToken, async (req, res) => {
    const safeConfig = sanitizeUserConfigPayload(req.body);

    try {
        await dbRunAsync(
            `INSERT INTO user_configs (
          user_id, theme, default_model, temperature, top_p, max_tokens,
          frequency_penalty, presence_penalty, system_prompt, thinking_mode, internet_mode, long_memory_enabled,
          font_preference, tab_title_mode, tab_title_custom_text, selection_explanation_delete_mode
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, COALESCE(?, 0), ?, ?, ?, COALESCE(?, 'promote_children'))
        ON CONFLICT(user_id) DO UPDATE SET
          theme = excluded.theme,
          default_model = excluded.default_model,
          temperature = excluded.temperature,
          top_p = excluded.top_p,
          max_tokens = excluded.max_tokens,
          frequency_penalty = excluded.frequency_penalty,
          presence_penalty = excluded.presence_penalty,
          system_prompt = excluded.system_prompt,
          thinking_mode = excluded.thinking_mode,
          internet_mode = excluded.internet_mode,
          long_memory_enabled = CASE
            WHEN ? IS NULL THEN user_configs.long_memory_enabled
            ELSE excluded.long_memory_enabled
          END,
          font_preference = excluded.font_preference,
          tab_title_mode = excluded.tab_title_mode,
          tab_title_custom_text = excluded.tab_title_custom_text,
          selection_explanation_delete_mode = CASE
            WHEN ? IS NULL THEN user_configs.selection_explanation_delete_mode
            ELSE excluded.selection_explanation_delete_mode
          END`,
            [
                req.user.userId, safeConfig.theme, safeConfig.default_model,
                safeConfig.temperature, safeConfig.top_p, safeConfig.max_tokens,
                safeConfig.frequency_penalty, safeConfig.presence_penalty, safeConfig.system_prompt,
                safeConfig.thinking_mode, safeConfig.internet_mode, safeConfig.long_memory_enabled,
                safeConfig.font_preference, safeConfig.tab_title_mode, safeConfig.tab_title_custom_text,
                safeConfig.selection_explanation_delete_mode,
                safeConfig.long_memory_enabled,
                safeConfig.selection_explanation_delete_mode
            ]
        );

        let memory = null;
        if (safeConfig.long_memory_enabled !== null) {
            memory = await setUserLongMemoryEnabled(req.user.userId, safeConfig.long_memory_enabled === 1);
        }

        let effectiveSelectionExplanationDeleteMode = safeConfig.selection_explanation_delete_mode;
        if (!effectiveSelectionExplanationDeleteMode) {
            const currentConfig = await dbGetAsync(
                `SELECT COALESCE(selection_explanation_delete_mode, 'promote_children') AS mode
                 FROM user_configs WHERE user_id = ?`,
                [req.user.userId]
            );
            effectiveSelectionExplanationDeleteMode = normalizeSelectionExplanationDeleteMode(
                currentConfig?.mode,
                'promote_children'
            );
        }

        console.log(` 用户配置已保存: userId=${req.user.userId}, systemPromptLength=${safeConfig.system_prompt.length}, longMemory=${memory ? memory.enabled : 'unchanged'}`);
        res.json({
            success: true,
            memory,
            selection_explanation_delete_mode: effectiveSelectionExplanationDeleteMode
        });
    } catch (err) {
        console.error(' 保存配置失败:', sanitizeReportContext(err));
        res.status(500).json({ error: '保存失败' });
    }
});

app.patch('/api/user/guide-state', guideStateLimiter, authenticateToken, async (req, res) => {
    const body = req.body || {};
    const hasMascotEnabled = Object.prototype.hasOwnProperty.call(body, 'mascotEnabled');
    const hasPetType = Object.prototype.hasOwnProperty.call(body, 'petType');
    const hasTapTargetEnabled = Object.prototype.hasOwnProperty.call(body, 'tapTargetEnabled');
    const hasCompletedVersion = Object.prototype.hasOwnProperty.call(body, 'completedVersion');

    if (!hasMascotEnabled && !hasPetType && !hasTapTargetEnabled && !hasCompletedVersion) {
        return res.status(400).json({ success: false, error: '没有提供可更新的引导状态字段' });
    }
    if (hasMascotEnabled && typeof body.mascotEnabled !== 'boolean') {
        return res.status(400).json({ success: false, error: 'mascotEnabled 必须是布尔值' });
    }
    if (hasPetType && !['saturn', 'tea'].includes(body.petType)) {
        return res.status(400).json({ success: false, error: 'petType 必须是 saturn 或 tea' });
    }
    if (hasTapTargetEnabled && typeof body.tapTargetEnabled !== 'boolean') {
        return res.status(400).json({ success: false, error: 'tapTargetEnabled 必须是布尔值' });
    }
    if (hasCompletedVersion && (!Number.isInteger(body.completedVersion) || body.completedVersion !== GUIDE_VERSION)) {
        return res.status(400).json({ success: false, error: `completedVersion 必须是整数且等于当前引导版本 ${GUIDE_VERSION}` });
    }

    const mascotEnabled = hasMascotEnabled ? (body.mascotEnabled ? 1 : 0) : null;
    const petType = hasPetType ? body.petType : null;
    const tapTargetEnabled = hasTapTargetEnabled ? (body.tapTargetEnabled ? 1 : 0) : null;
    const completedVersion = hasCompletedVersion ? body.completedVersion : null;

    try {
        await dbRunAsync(
            `INSERT INTO user_configs (user_id, guide_mascot_enabled, guide_pet_type, guide_tap_target_enabled, onboarding_completed_version)
        VALUES (?, COALESCE(?, 1), COALESCE(?, 'saturn'), COALESCE(?, 1), COALESCE(?, 0))
        ON CONFLICT(user_id) DO UPDATE SET
          guide_mascot_enabled = CASE
            WHEN ? IS NULL THEN user_configs.guide_mascot_enabled
            ELSE excluded.guide_mascot_enabled
          END,
          guide_pet_type = CASE
            WHEN ? IS NULL THEN user_configs.guide_pet_type
            ELSE excluded.guide_pet_type
          END,
          guide_tap_target_enabled = CASE
            WHEN ? IS NULL THEN user_configs.guide_tap_target_enabled
            ELSE excluded.guide_tap_target_enabled
          END,
          onboarding_completed_version = CASE
            WHEN ? IS NULL THEN user_configs.onboarding_completed_version
            ELSE excluded.onboarding_completed_version
          END`,
            [
                req.user.userId, mascotEnabled, petType, tapTargetEnabled, completedVersion,
                mascotEnabled, petType, tapTargetEnabled, completedVersion
            ]
        );

        const current = await dbGetAsync(
            `SELECT
          COALESCE(guide_mascot_enabled, 1) AS guide_mascot_enabled,
          COALESCE(guide_pet_type, 'saturn') AS guide_pet_type,
          COALESCE(guide_tap_target_enabled, 1) AS guide_tap_target_enabled,
          COALESCE(onboarding_completed_version, 0) AS onboarding_completed_version
        FROM user_configs WHERE user_id = ?`,
            [req.user.userId]
        );

        console.log(` 引导状态已保存: userId=${req.user.userId}, guideMascotEnabled=${current?.guide_mascot_enabled}, guidePetType=${current?.guide_pet_type}, guideTapTargetEnabled=${current?.guide_tap_target_enabled}, onboardingCompletedVersion=${current?.onboarding_completed_version}`);
        res.json({
            success: true,
            guideMascotEnabled: current?.guide_mascot_enabled === 1,
            guidePetType: current?.guide_pet_type === 'tea' ? 'tea' : 'saturn',
            guideTapTargetEnabled: current?.guide_tap_target_enabled === 1,
            onboardingCompletedVersion: Number(current?.onboarding_completed_version || 0)
        });
    } catch (err) {
        console.error(' 保存引导状态失败:', sanitizeReportContext(err));
        res.status(500).json({ error: '保存失败' });
    }
});

