app.get('/api/sessions', authenticateToken, async (req, res) => {
    try {
        await ensureSessionKindColumn();

        // 分页参数：offset（偏移量）和 limit（每页数量）
        const offset = parseBoundedInteger(req.query.offset, 0, 0, 100000);
        const limit = parseBoundedInteger(req.query.limit, 20, 1, 100);

        await Promise.all([ensureConversationOrganizationSchema(), ensureChatFlowSchemaColumns()]);
        const pinned = await dbAllAsync(
            `SELECT s.id, s.title, s.model, s.prompt_model_identity, s.prompt_language, s.session_kind, s.updated_at, s.created_at, COALESCE(s.messages_revision, 0) AS messages_revision, 1 AS pinned, p.position AS pin_position,
                    CASE WHEN f.id IS NULL THEN 0 ELSE 1 END AS has_canvas,
                    f.id AS flow_id, COALESCE(f.canvas_revision, 0) AS canvas_revision,
                    f.updated_at AS canvas_updated_at
             FROM session_pins p JOIN sessions s ON s.id = p.session_id AND s.user_id = p.user_id
             LEFT JOIN flows f ON f.session_id = s.id AND f.user_id = s.user_id
             WHERE p.user_id = ? AND s.is_archived = 0 AND COALESCE(s.session_kind, 'chat') IN ('chat', 'temporary_saved', 'flow')
             ORDER BY p.position ASC, s.id ASC`, [req.user.userId]
        );
        const sessions = await dbAllAsync(
            `SELECT s.id, s.title, s.model, s.prompt_model_identity, s.prompt_language, s.session_kind, s.updated_at, s.created_at, COALESCE(s.messages_revision, 0) AS messages_revision, 0 AS pinned, NULL AS pin_position,
                    CASE WHEN f.id IS NULL THEN 0 ELSE 1 END AS has_canvas,
                    f.id AS flow_id, COALESCE(f.canvas_revision, 0) AS canvas_revision,
                    f.updated_at AS canvas_updated_at
             FROM sessions s
             LEFT JOIN flows f ON f.session_id = s.id AND f.user_id = s.user_id
             WHERE s.user_id = ? AND s.is_archived = 0
               AND COALESCE(s.session_kind, 'chat') IN ('chat', 'temporary_saved', 'flow')
               AND NOT EXISTS (SELECT 1 FROM session_pins p WHERE p.user_id = s.user_id AND p.session_id = s.id)
             ORDER BY s.updated_at DESC, s.id DESC LIMIT ? OFFSET ?`, [req.user.userId, limit, offset]
        );
        return res.json({ pinned, sessions, hasMore: sessions.length === limit, offset, limit });
    } catch (error) {
        console.error(' 确保sessions表结构失败:', sanitizeReportContext(error));
        res.status(500).json({ error: '数据库结构初始化失败' });
    }
});

app.post('/api/sessions', authenticateToken, async (req, res) => {
    try {
        await ensureSessionKindColumn();

        const sessionId = `session_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
        const { title, model, prompt_model_identity: promptModelIdentity, session_kind: sessionKind = 'chat' } = req.body;
        const requestedTitle = String(title || '').trim();
        const fallbackTitle = String(sessionKind || 'chat') === 'temporary_saved' ? '临时对话' : '新对话';
        const safeTitle = sanitizeGeneratedConversationTitle(requestedTitle)
            || (requestedTitle && GENERIC_SESSION_TITLE_RE.test(requestedTitle) ? requestedTitle : fallbackTitle);

        db.run(
            'INSERT INTO sessions (id, user_id, title, model, prompt_model_identity, session_kind) VALUES (?, ?, ?, ?, ?, ?)',
            [sessionId, req.user.userId, safeTitle, model || 'auto', normalizeSessionPromptModelIdentity(promptModelIdentity), sessionKind || 'chat'],
            (err) => {
                if (err) {
                    console.error(' 创建会话失败:', sanitizeReportContext(err));
                    return res.status(500).json({ error: '创建失败' });
                }
                console.log(' 创建会话成功:', sessionId);
                scheduleConversationIntegritySeal(sessionId, req.user.userId);
                res.json({ success: true, sessionId, prompt_model_identity: normalizeSessionPromptModelIdentity(promptModelIdentity) });
            }
        );
    } catch (error) {
        console.error(' 确保sessions表结构失败:', sanitizeReportContext(error));
        res.status(500).json({ error: '数据库结构初始化失败' });
    }
});

app.post('/api/sessions/:id/prompt-identity', authenticateToken, async (req, res) => {
    try {
        await ensureSessionKindColumn();
        const requestedIdentity = normalizeSessionPromptModelIdentity(req.body?.prompt_model_identity);
        if (!requestedIdentity) return res.status(400).json({ error: '模型提示词身份无效' });
        const requestedLanguage = normalizeSessionPromptLanguage(req.body?.prompt_language) || 'zh-CN';

        const updated = await dbRunAsync(
            `UPDATE sessions
             SET prompt_model_identity = COALESCE(NULLIF(prompt_model_identity, ''), ?),
                 prompt_language = COALESCE(NULLIF(prompt_language, ''), ?)
             WHERE id = ? AND user_id = ?`,
            [requestedIdentity, requestedLanguage, req.params.id, req.user.userId]
        );
        if (Number(updated?.changes || 0) !== 1) return res.status(404).json({ error: '对话不存在' });

        const session = await dbGetAsync(
            'SELECT prompt_model_identity, prompt_language FROM sessions WHERE id = ? AND user_id = ?',
            [req.params.id, req.user.userId]
        );
        return res.json({
            success: true,
            prompt_model_identity: session?.prompt_model_identity || requestedIdentity,
            prompt_language: session?.prompt_language || requestedLanguage
        });
    } catch (error) {
        console.error(' 锁定会话模型提示词失败:', sanitizeReportContext(error));
        return res.status(500).json({ error: '无法锁定会话模型提示词' });
    }
});

app.put('/api/sessions/:id', authenticateToken, async (req, res) => {
    const { title, model, is_archived } = req.body;
    const safeTitle = title === undefined ? null : sanitizeGeneratedConversationTitle(title);
    const titleAction = String(req.body?.title_action || '').trim().toLowerCase();
    const isAiTitleSync = title !== undefined && titleAction === 'ai';
    if (title !== undefined && !safeTitle) {
        return res.status(400).json({ error: '对话标题不能为空或使用默认标题' });
    }

    try {
        await ensureChatFlowSchemaColumns();
        const updated = await withMainDbTransaction(async (tx) => {
            const result = isAiTitleSync
                ? await tx.run(
                    'UPDATE sessions SET title = ?, model = COALESCE(?, model), is_archived = COALESCE(?, is_archived), updated_at = CURRENT_TIMESTAMP WHERE id = ? AND user_id = ? AND COALESCE(title_user_locked, 0) = 0',
                    [safeTitle, model ?? null, is_archived ?? null, req.params.id, req.user.userId]
                )
                : await tx.run(
                    'UPDATE sessions SET title = COALESCE(?, title), title_user_locked = CASE WHEN ? IS NULL THEN title_user_locked ELSE 1 END, model = COALESCE(?, model), is_archived = COALESCE(?, is_archived), updated_at = CURRENT_TIMESTAMP WHERE id = ? AND user_id = ?',
                    [safeTitle, safeTitle, model ?? null, is_archived ?? null, req.params.id, req.user.userId]
                );
            if (Number(result?.changes || 0) !== 1) return false;
            if (safeTitle) {
                await tx.run(
                    'UPDATE flows SET title = ?, updated_at = CURRENT_TIMESTAMP WHERE session_id = ? AND user_id = ?',
                    [safeTitle, req.params.id, req.user.userId]
                );
            }
            return true;
        });
        if (!updated) return res.status(404).json({ error: '会话不存在' });
        scheduleConversationIntegritySeal(req.params.id, req.user.userId);
        return res.json({ success: true, ...(safeTitle ? { title: safeTitle } : {}) });
    } catch (error) {
        console.error(' 更新会话失败:', sanitizeReportContext(error));
        return res.status(500).json({ error: '更新失败' });
    }
});

app.post('/api/sessions/:id/title/regenerate', authLimiter, authenticateToken, async (req, res) => {
    const mode = String(req.body?.mode || 'regenerate').trim().toLowerCase();
    if (!['regenerate', 'continue_summary'].includes(mode)) {
        return res.status(400).json({ error: '标题生成模式无效' });
    }

    try {
        await ensureSessionKindColumn();
        const session = await dbGetAsync(
            `SELECT s.id, s.user_id, s.title, f.id AS flow_id
             FROM sessions s
             LEFT JOIN flows f ON f.session_id = s.id AND f.user_id = s.user_id
             WHERE s.id = ? AND s.user_id = ?
             LIMIT 1`,
            [req.params.id, req.user.userId]
        );
        if (!session) return res.status(404).json({ error: '会话不存在' });

        const rows = await dbAllAsync(
            `SELECT role, content FROM messages WHERE session_id = ? ORDER BY id ASC LIMIT 80`,
            [req.params.id]
        );
        const userContent = rows.filter((row) => row.role === 'user').at(-1)?.content || '';
        const assistantContent = rows
            .slice(mode === 'continue_summary' ? -24 : -12)
            .map((row) => `${row.role}: ${String(row.content || '').slice(0, 4000)}`)
            .join('\n');
        const uiLanguage = String(req.body?.uiLanguage || req.body?.language || req.headers['accept-language'] || 'zh-CN');
        const title = await generateFallbackConversationTitle({ userContent, assistantContent, uiLanguage });
        if (!title) return res.status(422).json({ error: '无法生成对话标题' });

        const saved = await updateSessionOrFlowTitleAndEmit({
            res: null,
            sessionId: req.params.id,
            flowId: session.flow_id,
            userId: req.user.userId,
            title,
            allowLockedTitle: true
        });
        if (!saved) return res.status(404).json({ error: '会话不存在' });
        return res.json({ success: true, title: saved, mode });
    } catch (error) {
        console.error(' AI 标题生成失败:', sanitizeReportContext(error));
        return res.status(503).json({ error: '暂时无法生成对话标题' });
    }
});

