function dbGetAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        db.get(query, params, (err, row) => {
            if (err) reject(err);
            else resolve(row);
        });
    });
}

function dbAllAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        db.all(query, params, (err, rows) => {
            if (err) reject(err);
            else resolve(rows || []);
        });
    });
}

function dbRunAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        db.run(query, params, function (err) {
            if (err) reject(err);
            else resolve(this);
        });
    });
}

function transactionDbGetAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        transactionDb.get(query, params, (err, row) => {
            if (err) reject(err);
            else resolve(row);
        });
    });
}

function transactionDbAllAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        transactionDb.all(query, params, (err, rows) => {
            if (err) reject(err);
            else resolve(rows || []);
        });
    });
}

function transactionDbRunAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        transactionDb.run(query, params, function (err) {
            if (err) reject(err);
            else resolve(this);
        });
    });
}

function enqueueMainDbTransaction(operation) {
    if (transactionDbClosing) {
        const error = new Error('transaction_database_closing');
        error.code = 'transaction_database_closing';
        return Promise.reject(error);
    }
    const run = transactionTail
        .catch(() => undefined)
        .then(async () => {
            await Promise.all([databaseSchemaReady, transactionDbReady]);
            return operation();
        });
    // A rejected transaction must not poison the FIFO for later requests.
    transactionTail = run.catch(() => undefined);
    return run;
}

function withMainDbTransaction(operation) {
    return enqueueMainDbTransaction(async () => {
        let began = false;
        try {
            await transactionDbRunAsync('BEGIN IMMEDIATE TRANSACTION');
            began = true;
            const result = await operation({
                get: transactionDbGetAsync,
                all: transactionDbAllAsync,
                run: transactionDbRunAsync
            });
            await transactionDbRunAsync('COMMIT');
            began = false;
            return result;
        } catch (error) {
            if (began) {
                try {
                    await transactionDbRunAsync('ROLLBACK');
                } catch (rollbackError) {
                    console.error(' 独立事务连接回滚失败:', sanitizeReportContext(rollbackError));
                }
            }
            throw error;
        }
    });
}

function withSensitiveAccountMutation(userId, mutate) {
    return runSensitiveAccountMutation({
        withTransaction: withMainDbTransaction,
        userId,
        mutate
    });
}

async function purgeStaleAuthSessionsAfterSensitiveChange(userId, reason) {
    try {
        return await authSessionStore.purgeStaleSessions(userId);
    } catch (error) {
        // The committed users.session_version is the authorization boundary.
        // This deletion is deliberately idempotent, post-commit housekeeping.
        console.warn(
            ` 敏感账户变更后的旧会话清理待重试: reason=${String(reason || 'sensitive_change').slice(0, 64)}, userId=${Number(userId) || 0}`,
            sanitizeReportContext(error)
        );
        return { deleted: 0, cleanupPending: true };
    }
}

async function closeTransactionDb() {
    transactionDbClosing = true;
    await transactionTail.catch(() => undefined);
    if (!transactionDb) {
        await transactionDbReady.catch(() => undefined);
    }
    if (!transactionDb) return;
    await new Promise((resolve) => {
        transactionDb.close((err) => {
            if (err) console.error(' 关闭事务数据库失败:', sanitizeReportContext(err));
            else console.log(' 事务数据库已关闭');
            resolve();
        });
    });
    transactionDb = null;
}

function selectionExplanationDbGetAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        selectionExplanationDb.get(query, params, (err, row) => {
            if (err) reject(err);
            else resolve(row);
        });
    });
}

function selectionExplanationDbAllAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        selectionExplanationDb.all(query, params, (err, rows) => {
            if (err) reject(err);
            else resolve(rows || []);
        });
    });
}

function selectionExplanationDbRunAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        selectionExplanationDb.run(query, params, function (err) {
            if (err) reject(err);
            else resolve(this);
        });
    });
}

function enqueueSelectionExplanationWrite(operation) {
    if (selectionExplanationDbClosing) {
        const error = new Error('selection_explanation_database_closing');
        error.code = 'selection_explanation_database_closing';
        return Promise.reject(error);
    }
    const run = selectionExplanationWriteTail
        .catch(() => undefined)
        .then(async () => {
            await Promise.all([databaseSchemaReady, selectionExplanationDbReady]);
            return operation();
        });
    selectionExplanationWriteTail = run.catch(() => undefined);
    return run;
}

function runSelectionExplanationWrite(operation) {
    return enqueueSelectionExplanationWrite(operation);
}

function withSelectionExplanationTransaction(operation) {
    return enqueueSelectionExplanationWrite(async () => {
        await selectionExplanationDbRunAsync('BEGIN IMMEDIATE TRANSACTION');
        try {
            const result = await operation({
                get: selectionExplanationDbGetAsync,
                all: selectionExplanationDbAllAsync,
                run: selectionExplanationDbRunAsync
            });
            await selectionExplanationDbRunAsync('COMMIT');
            return result;
        } catch (error) {
            await selectionExplanationDbRunAsync('ROLLBACK').catch(() => null);
            throw error;
        }
    });
}

function assertSelectionExplanationChanges(result, code) {
    if (Number(result?.changes || 0) !== 1) {
        const error = new Error(code);
        error.code = code;
        throw error;
    }
}

async function closeSelectionExplanationDb() {
    selectionExplanationDbClosing = true;
    await selectionExplanationWriteTail.catch(() => undefined);
    if (!selectionExplanationDb) {
        await selectionExplanationDbReady.catch(() => undefined);
    }
    if (!selectionExplanationDb) return;
    await new Promise((resolve) => {
        selectionExplanationDb.close((err) => {
            if (err) console.error(' 关闭选词解释数据库失败:', sanitizeReportContext(err));
            else console.log(' 选词解释数据库已关闭');
            resolve();
        });
    });
}

function passkeyDbGetAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        passkeyDb.get(query, params, (err, row) => {
            if (err) reject(err);
            else resolve(row);
        });
    });
}

function passkeyDbAllAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        passkeyDb.all(query, params, (err, rows) => {
            if (err) reject(err);
            else resolve(rows || []);
        });
    });
}

function passkeyDbRunAsync(query, params = []) {
    return new Promise((resolve, reject) => {
        passkeyDb.run(query, params, function (err) {
            if (err) reject(err);
            else resolve(this);
        });
    });
}

let passkeyTransactionTail = Promise.resolve();

function runPasskeySerialized(work) {
    const operation = passkeyTransactionTail.then(work, work);
    passkeyTransactionTail = operation.catch(() => null);
    return operation;
}

function runPasskeyTransaction(work) {
    return runPasskeySerialized(async () => {
        await passkeyDbRunAsync('BEGIN IMMEDIATE TRANSACTION');
        try {
            const result = await work();
            await passkeyDbRunAsync('COMMIT');
            return result;
        } catch (error) {
            await passkeyDbRunAsync('ROLLBACK').catch(() => null);
            throw error;
        }
    });
}

function createOpaquePasskeyToken() {
    return crypto.randomBytes(32).toString('base64url');
}

function hashOpaquePasskeyToken(value) {
    return crypto.createHash('sha256').update(String(value || '')).digest('hex');
}

function hashPasskeyUserAgent(req) {
    return crypto
        .createHash('sha256')
        .update(String(req?.headers?.['user-agent'] || ''))
        .digest('hex');
}

function normalizePasskeyLabel(value) {
    const label = String(value || '').normalize('NFKC').trim().replace(/\s+/g, ' ');
    if (!label || label.length > PASSKEY_LABEL_MAX_LENGTH) return '';
    if (/[<>\u0000-\u001F\u007F]/.test(label)) return '';
    return label;
}

function normalizePasskeyTransports(value) {
    const items = Array.isArray(value) ? value : [];
    return [...new Set(items
        .map((item) => String(item || '').trim())
        .filter((item) => PASSKEY_ALLOWED_TRANSPORTS.has(item)))]
        .slice(0, PASSKEY_ALLOWED_TRANSPORTS.size);
}

function parseStoredPasskeyTransports(value) {
    try {
        return normalizePasskeyTransports(JSON.parse(String(value || '[]')));
    } catch (error) {
        return [];
    }
}

function normalizePasskeyCredentialId(value) {
    const id = String(value || '').trim();
    return /^[A-Za-z0-9_-]{1,2048}$/.test(id) ? id : '';
}

function hasDisallowedCrossOriginWebAuthnClientData(response) {
    try {
        const encoded = String(response?.response?.clientDataJSON || '');
        if (!encoded) return true;
        const clientData = JSON.parse(Buffer.from(encoded, 'base64url').toString('utf8'));
        return clientData?.crossOrigin === true || !!clientData?.topOrigin;
    } catch (error) {
        return true;
    }
}

function buildPasskeyHttpError(message, statusCode = 400, code = 'passkey_error') {
    const error = new Error(message);
    error.statusCode = statusCode;
    error.code = code;
    return error;
}

function getPasskeyRequestContext(req) {
    const rawOrigin = String(req.headers.origin || '').trim();
    if (!rawOrigin) {
        throw buildPasskeyHttpError('通行密钥仅支持从网页安全连接使用', 400, 'passkey_origin_required');
    }

    let parsed;
    try {
        parsed = new URL(rawOrigin);
    } catch (error) {
        throw buildPasskeyHttpError('通行密钥请求来源无效', 400, 'passkey_origin_invalid');
    }

    const origin = parsed.origin;
    if (!allowedCorsOrigins.has(origin)) {
        throw buildPasskeyHttpError('通行密钥请求来源不受信任', 403, 'passkey_origin_not_allowed');
    }

    const hostname = parsed.hostname.toLowerCase();
    const isLocalhost = hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '::1';
    if (isLocalhost && !PASSKEY_ALLOW_LOCALHOST) {
        throw buildPasskeyHttpError('生产环境不允许使用 localhost 通行密钥', 403, 'passkey_localhost_not_allowed');
    }
    if (parsed.protocol !== 'https:' && !(parsed.protocol === 'http:' && isLocalhost)) {
        throw buildPasskeyHttpError('通行密钥需要 HTTPS 安全连接', 400, 'passkey_secure_context_required');
    }

    if (!hostname || hostname === 'tauri.localhost') {
        throw buildPasskeyHttpError('桌面端暂不支持通行密钥，请使用浏览器打开正式网站', 400, 'passkey_browser_required');
    }

    return { origin, rpID: hostname, secure: parsed.protocol === 'https:' };
}

function parseCookieHeader(req) {
    const output = {};
    String(req.headers.cookie || '').split(';').forEach((part) => {
        const separator = part.indexOf('=');
        if (separator <= 0) return;
        const key = part.slice(0, separator).trim();
        const value = part.slice(separator + 1).trim();
        if (!key) return;
        try {
            output[key] = decodeURIComponent(value);
        } catch (error) {
            output[key] = value;
        }
    });
    return output;
}

function getPasskeyLoginCookiePath(req) {
    try {
        const publicUrl = new URL(resolvePublicBaseUrl(req));
        const basePath = publicUrl.pathname.replace(/\/+$/, '');
        return `${basePath || ''}/api/auth/passkeys`;
    } catch (error) {
        return '/api/auth/passkeys';
    }
}

function setPasskeyLoginCookie(res, token, secure, req) {
    const parts = [
        `${PASSKEY_LOGIN_COOKIE}=${encodeURIComponent(token)}`,
        `Path=${getPasskeyLoginCookiePath(req)}`,
        'HttpOnly',
        'SameSite=Strict',
        `Max-Age=${Math.floor(PASSKEY_CHALLENGE_TTL_MS / 1000)}`
    ];
    if (secure) parts.push('Secure');
    res.setHeader('Set-Cookie', parts.join('; '));
}

function clearPasskeyLoginCookie(res, secure, req) {
    const parts = [
        `${PASSKEY_LOGIN_COOKIE}=`,
        `Path=${getPasskeyLoginCookiePath(req)}`,
        'HttpOnly',
        'SameSite=Strict',
        'Max-Age=0'
    ];
    if (secure) parts.push('Secure');
    res.setHeader('Set-Cookie', parts.join('; '));
}

function setPasskeyNoStore(res) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    res.setHeader('Pragma', 'no-cache');
}

async function cleanupPasskeyEphemeralState() {
    const now = Date.now();
    const consumedBefore = now - 24 * 60 * 60 * 1000;
    await runPasskeySerialized(async () => {
        await passkeyDbRunAsync(
            'DELETE FROM webauthn_challenges WHERE expires_at < ? OR (consumed_at IS NOT NULL AND consumed_at < ?)',
            [now, consumedBefore]
        );
        await passkeyDbRunAsync(
            'DELETE FROM user_reauth_grants WHERE expires_at < ? OR (consumed_at IS NOT NULL AND consumed_at < ?)',
            [now, consumedBefore]
        );
    }).catch((error) => {
        console.warn(' Passkey 临时状态清理失败:', sanitizeReportContext(error));
    });
}

async function getOrCreateWebAuthnUserHandle(userId) {
    const numericUserId = Number(userId);
    return runPasskeyTransaction(async () => {
        const existing = await passkeyDbGetAsync(
            'SELECT user_handle FROM webauthn_user_handles WHERE user_id = ?',
            [numericUserId]
        );
        if (existing?.user_handle) return String(existing.user_handle);

        const userHandle = crypto.randomBytes(32).toString('base64url');
        await passkeyDbRunAsync(
            'INSERT INTO webauthn_user_handles (user_id, user_handle, created_at) VALUES (?, ?, ?)',
            [numericUserId, userHandle, Date.now()]
        );
        return userHandle;
    });
}

async function createPasskeyChallengeRecord({ token, challenge, ceremony, userId = null, context, req }) {
    const now = Date.now();
    await runPasskeySerialized(() => passkeyDbRunAsync(
        `INSERT INTO webauthn_challenges
         (challenge_hash, challenge, ceremony, user_id, expected_rp_id, expected_origin, user_agent_hash, created_at, expires_at, consumed_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL)`,
        [
            hashOpaquePasskeyToken(token),
            String(challenge || ''),
            ceremony,
            userId || null,
            context.rpID,
            context.origin,
            hashPasskeyUserAgent(req),
            now,
            now + PASSKEY_CHALLENGE_TTL_MS
        ]
    ));
}

async function createPasskeyReauthGrant(userId, scope, authMethod) {
    const token = createOpaquePasskeyToken();
    const now = Date.now();
    await cleanupPasskeyEphemeralState();
    await runPasskeySerialized(() => passkeyDbRunAsync(
        `INSERT INTO user_reauth_grants
         (grant_hash, user_id, scope, auth_method, created_at, expires_at, consumed_at)
         VALUES (?, ?, ?, ?, ?, ?, NULL)`,
        [hashOpaquePasskeyToken(token), userId, scope, authMethod, now, now + PASSKEY_REAUTH_TTL_MS]
    ));
    return token;
}

function isRecentPasskeyEligibleSession(req, user) {
    const issuedAt = Number(req.user?.iat || 0);
    const age = Math.floor(Date.now() / 1000) - issuedAt;
    if (!Number.isFinite(age) || age < 0 || age > PASSKEY_RECENT_LOGIN_MAX_AGE_SECONDS) return false;

    const sessionProvider = String(req.user?.provider || '').trim();
    const externalProvider = String(user?.external_provider || '').trim();
    if (externalProvider && sessionProvider === externalProvider) return true;
    return String(req.user?.auth_method || '') === 'passkey';
}

async function verifyPasskeyReauthentication(req, user, body = {}) {
    const currentPassword = typeof body.currentPassword === 'string' ? body.currentPassword : '';
    const twoFactorCode = typeof body.twoFactorCode === 'string' ? body.twoFactorCode : '';
    let authMethod = '';

    if (currentPassword) {
        if (validateExistingPasswordInput(currentPassword, '当前密码')) {
            throw buildPasskeyHttpError('当前密码错误', 401, 'passkey_reauth_password_invalid');
        }
        const matched = await verifyPassword(currentPassword, user.password_hash).catch(() => false);
        if (!matched) {
            throw buildPasskeyHttpError('当前密码错误', 401, 'passkey_reauth_password_invalid');
        }
        authMethod = 'password';
    } else if (isRecentPasskeyEligibleSession(req, user)) {
        authMethod = String(req.user?.auth_method || req.user?.provider || 'recent_login');
    } else {
        throw buildPasskeyHttpError(
            user.external_provider
                ? '请先重新使用已绑定的登录方式登录，再管理通行密钥'
                : '请输入当前密码以继续',
            401,
            'passkey_reauth_required'
        );
    }

    const twoFactorEnabled = Number(user.two_factor_enabled || 0) === 1
        && hasUsableUserTotpSecret(user);
    if (twoFactorEnabled && !await consumeUserSecondFactor(user, twoFactorCode)) {
        throw buildPasskeyHttpError('Authenticator 验证码无效', 401, 'passkey_reauth_totp_invalid');
    }

    return authMethod;
}

async function awardSecuritySetupRewardUsingTransaction(tx, userId, reward, metadata = {}) {
    const points = Number(reward?.points || 0);
    const taskKey = String(reward?.key || '').trim();
    if (!taskKey || points <= 0) return 0;

    const insert = await tx.run(
        `INSERT OR IGNORE INTO user_task_rewards (user_id, task_key, points, metadata, completed_at)
         VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)`,
        [userId, taskKey, points, JSON.stringify(metadata || {})]
    );
    if (Number(insert?.changes || 0) !== 1) return 0;

    await tx.run(
        'UPDATE users SET points = COALESCE(points, 0) + ? WHERE id = ?',
        [points, userId]
    );
    return points;
}

async function awardSecuritySetupRewardWithinTransaction(userId, reward, metadata = {}) {
    return awardSecuritySetupRewardUsingTransaction(
        { run: passkeyDbRunAsync },
        userId,
        reward,
        metadata
    );
}

async function awardSecuritySetupReward(userId, reward, metadata = {}) {
    await databaseSchemaReady;
    return runPasskeyTransaction(() => awardSecuritySetupRewardWithinTransaction(userId, reward, metadata));
}

function passkeyValuesEqual(left, right) {
    try {
        const leftText = String(left || '');
        const rightText = String(right || '');
        if (!/^[A-Za-z0-9_-]+$/.test(leftText) || !/^[A-Za-z0-9_-]+$/.test(rightText)) return false;
        const leftBuffer = Buffer.from(leftText, 'base64url');
        const rightBuffer = Buffer.from(rightText, 'base64url');
        return leftBuffer.length > 0
            && leftBuffer.length === rightBuffer.length
            && crypto.timingSafeEqual(leftBuffer, rightBuffer);
    } catch (error) {
        return false;
    }
}

async function consumePasskeyChallengeAttempt({ token, ceremony, userId = null, context, req }) {
    const tokenHash = hashOpaquePasskeyToken(token);
    const expectedUserId = userId === null ? null : Number(userId);
    const result = await runPasskeyTransaction(async () => {
        const row = await passkeyDbGetAsync(
            'SELECT * FROM webauthn_challenges WHERE challenge_hash = ?',
            [tokenHash]
        );
        if (!row || row.consumed_at) {
            return { ok: false, reason: 'missing_or_consumed' };
        }

        const now = Date.now();
        const update = await passkeyDbRunAsync(
            `UPDATE webauthn_challenges
             SET consumed_at = ?
             WHERE challenge_hash = ? AND consumed_at IS NULL`,
            [now, tokenHash]
        );
        if (Number(update?.changes || 0) !== 1) {
            return { ok: false, reason: 'consumed_concurrently' };
        }

        const storedUserId = row.user_id === null ? null : Number(row.user_id);
        const valid = String(row.ceremony || '') === ceremony
            && Number(row.expires_at || 0) > now
            && String(row.expected_rp_id || '') === context.rpID
            && String(row.expected_origin || '') === context.origin
            && String(row.user_agent_hash || '') === hashPasskeyUserAgent(req)
            && storedUserId === expectedUserId;
        return valid
            ? { ok: true, row }
            : { ok: false, reason: 'challenge_context_mismatch' };
    });

    if (!result.ok) {
        throw buildPasskeyHttpError('通行密钥验证已过期，请重试', 401, result.reason);
    }
    return result.row;
}

async function consumePasskeyReauthGrantUsingTransaction(tx, { token, userId, scope }) {
    const grantHash = hashOpaquePasskeyToken(token);
    const numericUserId = Number(userId);
    const row = await tx.get(
        'SELECT * FROM user_reauth_grants WHERE grant_hash = ?',
        [grantHash]
    );
    if (!row || row.consumed_at) {
        throw buildPasskeyHttpError('安全验证已过期，请重新验证', 401, 'passkey_reauth_grant_invalid');
    }

    const now = Date.now();
    const valid = Number(row.user_id) === numericUserId
        && String(row.scope || '') === scope
        && Number(row.expires_at || 0) > now;
    const update = await tx.run(
        `UPDATE user_reauth_grants
         SET consumed_at = ?
         WHERE grant_hash = ? AND consumed_at IS NULL`,
        [now, grantHash]
    );

    if (!valid || Number(update?.changes || 0) !== 1) {
        throw buildPasskeyHttpError('安全验证已过期，请重新验证', 401, 'passkey_reauth_grant_invalid');
    }
}

async function consumePasskeyReauthGrantWithinTransaction(args) {
    return consumePasskeyReauthGrantUsingTransaction(
        { get: passkeyDbGetAsync, run: passkeyDbRunAsync },
        args
    );
}

async function consumePasskeyReauthGrant(args) {
    return runPasskeyTransaction(() => consumePasskeyReauthGrantWithinTransaction(args));
}

function buildStoredPasskeyCredential(row) {
    return {
        id: String(row.credential_id || ''),
        publicKey: new Uint8Array(Buffer.from(row.public_key)),
        counter: Math.max(0, Number(row.sign_count || 0)),
        transports: parseStoredPasskeyTransports(row.transports_json)
    };
}

function formatPublicPasskeyRow(row) {
    return {
        id: Number(row.id),
        label: String(row.label || ''),
        domain: String(row.rp_id || ''),
        enabled: Number(row.enabled || 0) === 1,
        status: Number(row.enabled || 0) === 1 ? 'active' : 'pending',
        deviceType: String(row.credential_device_type || ''),
        backedUp: Number(row.credential_backed_up || 0) === 1,
        transports: parseStoredPasskeyTransports(row.transports_json),
        createdAt: Number(row.created_at || 0),
        verifiedAt: row.verified_at ? Number(row.verified_at) : null,
        lastUsedAt: row.last_used_at ? Number(row.last_used_at) : null
    };
}

function sendPasskeyRouteError(res, error, fallbackMessage) {
    const statusCode = Number(error?.statusCode || 0);
    if (statusCode >= 400 && statusCode < 500) {
        return res.status(statusCode).json({
            success: false,
            error: error.message || fallbackMessage,
            code: error.code || 'passkey_error'
        });
    }
    console.error(` ${fallbackMessage}:`, sanitizeReportContext(error));
    return res.status(500).json({ success: false, error: fallbackMessage, code: 'passkey_internal_error' });
}

function buildEmailCodeMessage({ purpose, code }) {
    const brand = BRAND_TITLE || 'RAI';
    const safeBrand = escapeEmailHtml(brand);
    const safeCode = escapeEmailHtml(code);
    const purposeLabel = purpose === 'register'
        ? '验证注册邮箱'
        : purpose === 'password_reset'
            ? '重置密码'
            : '验证码登录';
    const subject = `${brand} ${purposeLabel}验证码`;
    const intro = purpose === 'register'
        ? `你正在创建 ${brand} 账号，请输入下面的验证码完成邮箱验证。`
        : purpose === 'password_reset'
            ? `你正在重置 ${brand} 密码，请输入下面的验证码继续。`
            : `你正在使用邮箱验证码登录 ${brand}。`;
    const minutes = Math.max(1, Math.round(EMAIL_CODE_TTL_MS / 60000));
    const html = [
        '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;line-height:1.6;color:#111827;padding:24px">',
        `<h2 style="margin:0 0 12px">${safeBrand}</h2>`,
        `<p style="margin:0 0 18px">${escapeEmailHtml(intro)}</p>`,
        `<div style="font-size:32px;font-weight:700;letter-spacing:0.18em;padding:14px 18px;background:#f3f4f6;border-radius:12px;display:inline-block">${safeCode}</div>`,
        `<p style="margin:18px 0 0;color:#6b7280;font-size:14px">验证码 ${minutes} 分钟内有效。若不是你本人操作，可以忽略这封邮件。</p>`,
        '</div>'
    ].join('');
    const text = `${brand}\n\n${intro}\n\n验证码: ${code}\n\n验证码 ${minutes} 分钟内有效。若不是你本人操作，可以忽略这封邮件。`;
    return { subject, html, text };
}

function hashPendingEmailChangeCode({ userId, email, code }) {
    const normalizedCode = normalizeEmailCodeInput(code);
    return crypto
        .createHmac('sha256', JWT_SECRET)
        .update(`${Number(userId) || 0}:email_change:${normalizeEmailForAuth(email)}:${normalizedCode}`)
        .digest('hex');
}

function hashPendingEmailCurrentCode({ userId, currentEmail, pendingEmail, code }) {
    const normalizedCode = normalizeEmailCodeInput(code);
    return crypto
        .createHmac('sha256', JWT_SECRET)
        .update(`${Number(userId) || 0}:email_change_current:${normalizeEmailForAuth(currentEmail)}:${normalizeEmailForAuth(pendingEmail)}:${normalizedCode}`)
        .digest('hex');
}

function buildEmailChangeCodeMessage({ email, code, currentEmail = '', kind = 'new' }) {
    const brand = BRAND_TITLE || 'RAI';
    const safeBrand = escapeEmailHtml(brand);
    const safeCode = escapeEmailHtml(code);
    const safeEmail = escapeEmailHtml(email);
    const safeCurrentEmail = escapeEmailHtml(currentEmail);
    const minutes = Math.max(1, Math.round(EMAIL_CODE_TTL_MS / 60000));
    const isCurrent = kind === 'current';
    const subject = isCurrent ? `${brand} 修改邮箱旧邮箱验证码` : `${brand} 修改邮箱新邮箱验证码`;
    const intro = isCurrent
        ? `你正在把 ${brand} 登录邮箱从 ${currentEmail} 改为 ${email}，请输入下面的旧邮箱验证码确认这是你本人操作。`
        : `你正在把 ${brand} 登录邮箱改为 ${email}，请输入下面的新邮箱验证码确认这个邮箱可用。`;
    const html = [
        '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;line-height:1.6;color:#111827;padding:24px">',
        `<h2 style="margin:0 0 12px">${safeBrand}</h2>`,
        isCurrent
            ? `<p style="margin:0 0 18px">你正在把登录邮箱从 <strong>${safeCurrentEmail}</strong> 改为 <strong>${safeEmail}</strong>，请输入下面的旧邮箱验证码确认这是你本人操作。</p>`
            : `<p style="margin:0 0 18px">你正在把登录邮箱改为 <strong>${safeEmail}</strong>，请输入下面的新邮箱验证码确认这个邮箱可用。</p>`,
        `<div style="font-size:32px;font-weight:700;letter-spacing:0.18em;padding:14px 18px;background:#f3f4f6;border-radius:12px;display:inline-block">${safeCode}</div>`,
        `<p style="margin:18px 0 0;color:#6b7280;font-size:14px">验证码 ${minutes} 分钟内有效。若不是你本人操作，请立即修改密码并开启二步验证。</p>`,
        '</div>'
    ].join('');
    const text = `${brand}\n\n${intro}\n\n验证码: ${code}\n\n验证码 ${minutes} 分钟内有效。若不是你本人操作，请立即修改密码并开启二步验证。`;
    return { subject, html, text };
}

async function issuePendingEmailChangeCode({ userId, currentEmail, email, req }) {
    const normalizedCurrentEmail = normalizeEmailForAuth(currentEmail);
    const normalizedEmail = normalizeEmailForAuth(email);
    if (!Number.isInteger(Number(userId)) || Number(userId) <= 0 || !isValidEmailForAuth(normalizedCurrentEmail) || !isValidEmailForAuth(normalizedEmail)) {
        throw new Error('invalid_email_change_request');
    }

    const currentCode = generateEmailCode();
    const currentCodeHash = hashPendingEmailCurrentCode({
        userId,
        currentEmail: normalizedCurrentEmail,
        pendingEmail: normalizedEmail,
        code: currentCode
    });
    const expiresAt = Date.now() + EMAIL_CODE_TTL_MS;
    await dbRunAsync(
        `UPDATE users
         SET pending_email = ?,
             pending_email_current_code_hash = ?,
             pending_email_current_verified_at = NULL,
             pending_email_code_hash = NULL,
             pending_email_expires_at = ?
         WHERE id = ?`,
        [normalizedEmail, currentCodeHash, expiresAt, userId]
    );

    const currentMessage = buildEmailChangeCodeMessage({
        email: normalizedEmail,
        currentEmail: normalizedCurrentEmail,
        code: currentCode,
        kind: 'current'
    });
    try {
        await sendResendEmail({
            to: normalizedCurrentEmail,
            subject: currentMessage.subject,
            html: currentMessage.html,
            text: currentMessage.text
        });
    } catch (error) {
        await dbRunAsync(
            `UPDATE users
             SET pending_email = NULL,
                 pending_email_current_code_hash = NULL,
                 pending_email_current_verified_at = NULL,
                 pending_email_code_hash = NULL,
                 pending_email_expires_at = NULL
             WHERE id = ? AND pending_email_current_code_hash = ?`,
            [userId, currentCodeHash]
        ).catch(() => null);
        appendRaiRuntimeReport({
            level: '报错',
            tag: 'email_change_code',
            message: `修改邮箱验证码发送失败: ${error.message}`,
            context: {
                userId,
                currentEmailDomain: String(normalizedCurrentEmail).split('@')[1] || '',
                emailDomain: String(normalizedEmail).split('@')[1] || '',
                code: error.code || null,
                status: error.status || null,
                response: error.response || null
            }
        });
        throw error;
    }

    console.log(` 修改邮箱旧邮箱验证码已发送: userId=${userId}, ${formatPrivateLogFingerprint(normalizedCurrentEmail.split('@')[1] || '', 'currentDomain')}, ${formatPrivateLogFingerprint(normalizedEmail.split('@')[1] || '', 'pendingDomain')}`);
    return { pending_email: normalizedEmail, pending_email_expires_at: expiresAt, pending_email_stage: 'current' };
}

async function verifyPendingEmailCurrentCodeAndIssueNewCode({ userId, email = '', currentEmailCode = '', req }) {
    const numericUserId = Number(userId);
    const normalizedEmail = normalizeEmailForAuth(email);
    const normalizedCurrentEmailCode = normalizeEmailCodeInput(currentEmailCode);
    if (!Number.isInteger(numericUserId) || numericUserId <= 0 || !isValidEmailForAuth(normalizedEmail) || !isValidEmailCodeInput(normalizedCurrentEmailCode)) {
        const error = new Error('旧邮箱验证码无效或已过期');
        error.statusCode = 400;
        throw error;
    }

    const newCode = generateEmailCode();
    const newCodeHash = hashPendingEmailChangeCode({ userId: numericUserId, email: normalizedEmail, code: newCode });
    const expiresAt = Date.now() + EMAIL_CODE_TTL_MS;
    let user;

    await withMainDbTransaction(async (tx) => {
        user = await tx.get(
            `SELECT id, email, pending_email, pending_email_current_code_hash, pending_email_expires_at
             FROM users
             WHERE id = ?`,
            [numericUserId]
        );
        if (!user) {
            const error = new Error('用户不存在');
            error.statusCode = 404;
            throw error;
        }

        const pendingEmail = normalizeEmailForAuth(user.pending_email);
        if (!pendingEmail || pendingEmail !== normalizedEmail) {
            const error = new Error('没有待确认的新邮箱');
            error.statusCode = 400;
            throw error;
        }
        if (Number(user.pending_email_expires_at || 0) <= Date.now()) {
            const error = new Error('旧邮箱验证码无效或已过期');
            error.statusCode = 400;
            throw error;
        }
        const expectedCurrentHash = hashPendingEmailCurrentCode({
            userId: numericUserId,
            currentEmail: user.email,
            pendingEmail,
            code: normalizedCurrentEmailCode
        });
        if (!safeCompareText(expectedCurrentHash, user.pending_email_current_code_hash || '')) {
            const error = new Error('旧邮箱验证码无效或已过期');
            error.statusCode = 400;
            throw error;
        }

        const updateResult = await tx.run(
            `UPDATE users
             SET pending_email_current_verified_at = ?,
                 pending_email_code_hash = ?,
                 pending_email_expires_at = ?
             WHERE id = ?
               AND pending_email = ?
               AND pending_email_current_code_hash = ?`,
            [Date.now(), newCodeHash, expiresAt, numericUserId, pendingEmail, user.pending_email_current_code_hash]
        );
        if (Number(updateResult?.changes || 0) !== 1) {
            const error = new Error('邮箱验证状态已变化，请重试');
            error.statusCode = 409;
            error.code = 'pending_email_state_changed';
            throw error;
        }
    });

    const message = buildEmailChangeCodeMessage({
        email: normalizedEmail,
        currentEmail: normalizeEmailForAuth(user.email),
        code: newCode,
        kind: 'new'
    });
    try {
        await sendResendEmail({
            to: normalizedEmail,
            subject: message.subject,
            html: message.html,
            text: message.text
        });
    } catch (error) {
        await dbRunAsync(
            `UPDATE users
             SET pending_email_code_hash = NULL
             WHERE id = ? AND pending_email_code_hash = ?`,
            [numericUserId, newCodeHash]
        ).catch(() => null);
        appendRaiRuntimeReport({
            level: '报错',
            tag: 'email_change_new_code',
            message: `修改邮箱新邮箱验证码发送失败: ${error.message}`,
            context: {
                userId: numericUserId,
                emailDomain: String(normalizedEmail).split('@')[1] || '',
                code: error.code || null,
                status: error.status || null,
                response: error.response || null
            }
        });
        throw error;
    }

    console.log(` 修改邮箱新邮箱验证码已发送: userId=${numericUserId}, ${formatPrivateLogFingerprint(normalizedEmail.split('@')[1] || '', 'pendingDomain')}`);
    return { pending_email: normalizedEmail, pending_email_expires_at: expiresAt, pending_email_stage: 'new' };
}

async function verifyPendingEmailChange({ userId, email = '', code = '' }) {
    const numericUserId = Number(userId);
    const normalizedEmail = normalizeEmailForAuth(email);
    const normalizedCode = normalizeEmailCodeInput(code);
    if (!Number.isInteger(numericUserId) || numericUserId <= 0 || !isValidEmailCodeInput(normalizedCode)) {
        const error = new Error('验证码无效或已过期');
        error.statusCode = 400;
        throw error;
    }

    const mutation = await withSensitiveAccountMutation(numericUserId, async (tx) => {
        const user = await tx.get(
            `SELECT id, email, username, avatar_url, external_provider, external_uid,
                    pending_email, pending_email_current_verified_at, pending_email_code_hash, pending_email_expires_at
             FROM users
             WHERE id = ?`,
            [numericUserId]
        );
        if (!user) {
            const error = new Error('用户不存在');
            error.statusCode = 404;
            throw error;
        }

        const pendingEmail = normalizeEmailForAuth(user.pending_email);
        if (!pendingEmail || (normalizedEmail && normalizedEmail !== pendingEmail)) {
            const error = new Error('没有待确认的新邮箱');
            error.statusCode = 400;
            throw error;
        }
        if (!isValidEmailForAuth(pendingEmail) || Number(user.pending_email_expires_at || 0) <= Date.now()) {
            const error = new Error('验证码无效或已过期');
            error.statusCode = 400;
            throw error;
        }
        if (!user.pending_email_current_verified_at || !user.pending_email_code_hash) {
            const error = new Error('请先验证旧邮箱验证码');
            error.statusCode = 400;
            throw error;
        }
        const expectedHash = hashPendingEmailChangeCode({
            userId: numericUserId,
            email: pendingEmail,
            code: normalizedCode
        });
        if (!safeCompareText(expectedHash, user.pending_email_code_hash || '')) {
            const error = new Error('新邮箱验证码无效或已过期');
            error.statusCode = 400;
            throw error;
        }

        const duplicate = await tx.get(
            'SELECT id FROM users WHERE LOWER(email) = LOWER(?) AND id != ?',
            [pendingEmail, numericUserId]
        );
        if (duplicate) {
            const error = new Error('该邮箱已被其他账号使用');
            error.statusCode = 409;
            throw error;
        }

        const updateResult = await tx.run(
            `UPDATE users
             SET email = ?,
                 email_verified = 1,
                 email_verified_at = CURRENT_TIMESTAMP,
                 pending_email = NULL,
                 pending_email_current_code_hash = NULL,
                 pending_email_current_verified_at = NULL,
                 pending_email_code_hash = NULL,
                 pending_email_expires_at = NULL
             WHERE id = ?`,
            [pendingEmail, numericUserId]
        );
        if (Number(updateResult?.changes || 0) !== 1) {
            const error = new Error('邮箱验证状态已变化，请重试');
            error.statusCode = 409;
            error.code = 'pending_email_state_changed';
            throw error;
        }

        return {
            ...user,
            email: pendingEmail,
            pending_email: null,
            pending_email_current_code_hash: null,
            pending_email_current_verified_at: null,
            pending_email_code_hash: null,
            pending_email_expires_at: null
        };
    });
    return { ...mutation.value, session_version: mutation.sessionVersion };
}

async function sendResendEmail({ to, subject, html, text }) {
    if (!RESEND_API_KEY) {
        const error = new Error('resend_api_key_missing');
        error.code = 'email_service_not_configured';
        throw error;
    }
    if (!RESEND_FROM_EMAIL) {
        const error = new Error('resend_from_email_invalid');
        error.code = 'email_from_invalid';
        error.response = {
            message: 'RESEND_FROM_EMAIL/RAI_EMAIL_FROM must be email@example.com or Name <email@example.com>'
        };
        throw error;
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), RESEND_TIMEOUT_MS);
    let response;
    try {
        response = await fetch(RESEND_API_URL, {
            method: 'POST',
            signal: controller.signal,
            headers: {
                'Authorization': `Bearer ${RESEND_API_KEY}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                from: RESEND_FROM_EMAIL,
                to,
                subject,
                html,
                text
            })
        });
    } catch (error) {
        if (error?.name === 'AbortError') {
            const timeoutError = new Error('resend_email_timeout');
            timeoutError.code = 'email_timeout';
            throw timeoutError;
        }
        throw error;
    } finally {
        clearTimeout(timeout);
    }

    const rawBody = await readBoundedResponseText(response, 256 * 1024).catch(() => '');
    let parsedBody = null;
    try {
        parsedBody = rawBody ? JSON.parse(rawBody) : null;
    } catch (error) {
        parsedBody = null;
    }

	    if (!response.ok) {
	        const error = new Error(`resend_email_failed_${response.status}`);
	        error.status = response.status;
	        error.response = parsedBody;
	        const responseMessage = String(parsedBody?.message || parsedBody?.error || '').trim();
	        if (response.status === 403 && /only send testing emails|verify a domain/i.test(responseMessage)) {
	            error.code = 'resend_testing_domain_restricted';
	        }
	        throw error;
	    }

    return parsedBody || {};
}

